"""Append C204 (idempotent): my own prediction was wrong -- the 384 split holds 0.958, the 224 split does not."""
import io, os

p = 'state/FACTS.md'
ADD = """| C204 | ⚠️📊 **【我昨天的预测【错了】：384 的 plain/TTA 拆分 = 0.958（我预测 0.957），而 224 的同款拆分确实是 0.957】——两条臂对同一改动给出相反结果。**<br>**① 读数**：`57394596`（384 拆分，C198）= **0.958**；`57377106`（224 拆分，C197）= **0.957**。两者**改动完全相同**（把一条 TTA 臂的秩与其 plain 秩 0.5/0.5 平均）,只是**权重不同**（384 占 Raptor half 的 0.65、224 占 0.35）。<br>**② ⇒ 我昨天的预登记预测（"C198 先验转负 ⇒ `57394596` 预计 0.957"）被证伪。如实记下**：我当时用的是**单一机制的类比**（"同一机制在权重更大的臂上应该更糟"）,而真实结果是**只有权重较小的那条臂被拆坏**。<br>**③ 一个诚实但未验证的解释**：384 臂的 TTA（0.5*(plain+mirror)）在两个视图上**更接近**（同一 320 场、只是镜像）,所以它的 plain 与 TTA 秩**高度相关**,对半分几乎不改变混合;而 224 臂是 0.8 中心裁剪后的另一分辨率,plain 与 TTA 差异更大,对半分就把一条本该相加的信息**拆成了两个半权**。**⇒ 这是一个可检验的假设**（若成立,`spearman(plain, tta)` 应满足 384 > 224）;<br>**④ ⇒ 顺带一个可用的副产品**：我们现在有**两条 0.958 且做了最多视图平均**的产物 —— `57376589`（+224 镜像）与 **`57394596`（+224/384 双拆分）**。它们显示分与 `57250245` 相同,但**平均的视图更多**。⇒ 若认为"更多平均 ⇒ 未取整分更高",它们应是 tick① 的候选。<br>**⑤ 教训（第 N 次,同类）**：**"机制相同 ⇒ 结果同向"是错的**。C201 我把 laimer 的"未验证"当成"弱正"错了;C204 我又把"同机制"当成"同结果"错了。**⇒ 规则：预测必须绑定到【被测的那条臂】,不能用另一条臂的读数外推。** | 2026-10-20 |
"""

if '| C204 |' in io.open(p, encoding='utf-8').read():
    raise SystemExit('REFUSING: C204 is already present')
with io.open(p, 'a', encoding='utf-8') as fh:
    fh.write(ADD)
print('appended C204; file now', os.path.getsize(p), 'bytes')
